"""Compare generic char counter facade and exact selected native abstract methods."""
import argparse,hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];EVIDENCE=ROOT/'planning/stage-2/repos/dotj-core/evidence'
def csv(v):return ','.join(map(str,v))
def main():
 p=argparse.ArgumentParser();p.add_argument('--jar',type=Path);a=p.parse_args()
 if a.jar is None:a.jar=ROOT/json.loads((EVIDENCE/'foundation-product-candidate-v1.json').read_text(encoding='utf-8'))['jarPath']
 path=EVIDENCE/'generic-encoding-char-counter-contract-v10.0.12.json';j=json.loads(path.read_text(encoding='utf-8'));assert j['runtimeVersion']=='10.0.12' and j['coreLibSha256']=='1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678';assert j['oracleSha256']==hashlib.sha256(Path(__file__).with_name('capture-generic-encoding-char-counter-contract.ps1').read_bytes()).hexdigest();assert len(j['rows'])==1344 and len(j['abstracts'])==6
 assert {r['result'].get('exception') for r in j['rows']}<={None,'System.ArgumentNullException','System.InvalidOperationException','System.OverflowException','System.OutOfMemoryException'}
 lines=[]
 for row in j['rows']:
  r=row['result'];lines.append('\t'.join([str(row['multiplier']),str(row['countMode']),str(row['length']),row['operation'],str(row['form']),str(int(row['flush'])),str(int(r['ok'])),str(r.get('count',0)),csv(r.get('units',[])),r.get('exception',''),str(r.get('hResult',0)),r.get('paramName') or '~',';'.join(csv(t) for t in row['trace'])]))
 work=Path('D:/AI/Implementation/dotj Frameworks/verification/generic-encoding-char-counter');work.mkdir(parents=True,exist_ok=True);vectors=work/'vectors.tsv';vectors.write_text('\n'.join(lines)+'\n',encoding='ascii');abstracts=work/'abstracts.txt';abstracts.write_text('\n'.join(j['abstracts'])+'\n',encoding='ascii');component=Path(__file__).with_name('generic-encoding-char-counter-probe.java');source=work/'GenericEncodingCharCounterProbe.java';source.write_bytes(component.read_bytes());subprocess.run(['javac','--release','21','-cp',str(a.jar),'-d',str(work),str(source)],check=True);result=subprocess.run(['java','-cp',str(a.jar)+';'+str(work),'GenericEncodingCharCounterProbe',str(vectors),str(abstracts)],capture_output=True,text=True);print(result.stdout,end='');print(result.stderr,end='');result.check_returncode();assert 'groups=2695' in result.stdout
 bad=work/'WholeOnlyCounter.java';bad.write_text('import System.Text.*;import System.Byte;class WholeOnlyCounter extends Encoding{public int GetByteCount(char[] c,int i,int n){return 0;}public int GetCharCount(Byte[] b){return 0;}public int GetBytes(char[] c,int i,int n,Byte[] b,int o){return 0;}public int GetChars(Byte[] b,int i,int n,char[] c,int o){return 0;}public int GetMaxByteCount(int n){return 0;}public int GetMaxCharCount(int n){return 0;}}',encoding='utf-8',newline='\n');result=subprocess.run(['javac','--release','21','-cp',str(a.jar),'-d',str(work),str(bad)],capture_output=True,text=True);assert result.returncode!=0 and 'GetCharCount' in result.stderr and 'does not override abstract method' in result.stderr
 record=dict(schemaVersion=1,casesPassed=2695,nativeCases=1344,nativeAbstractMethods=6,minimalSixMethodSubclass=True,missingRangeCounterCompileRejection=True,oracleEvidence=path.name,oracleSha256=hashlib.sha256(path.read_bytes()).hexdigest(),consumerSourceSha256=hashlib.sha256(component.read_bytes()).hexdigest(),candidateJarSha256=hashlib.sha256(a.jar.read_bytes()).hexdigest(),qualification='SELECTED_GENERIC_ENCODING_CHAR_COUNTER_AND_ABSTRACT_SURFACE_ONLY; DIRECT_POINTERS_REENTRANCY_FULL_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN');(EVIDENCE/'generic-encoding-char-counter-differential-v1.json').write_text(json.dumps(record,indent=2)+'\n',encoding='utf-8',newline='\n');print('PASS generic char counter: 1344 native cases, six abstract methods, 2695 groups and one compile rejection')
